mapper.delete:
DELETE FROM feed_index_queue q USING (VALUES
(#{k.itemType}::varchar, #{k.itemId}::uuid, #{k.queuedAt}::timestamp)
) AS v(item_type, item_id, queued_at) WHERE q.item_type = v.item_type AND q.item_id = v.item_id AND q.queued_at <= v.queued_at

mapper.update:
UPDATE feed_items fi SET quality_score = v.q, engagement_score = v.e, recommend_ok = v.ok FROM (VALUES
(#{r.itemType}::varchar, #{r.itemId}::uuid, #{r.qualityScore}::real, #{r.engagementScore}::real, #{r.recommendOk}::boolean)
) AS v(item_type, item_id, q, e, ok) WHERE fi.item_type = v.item_type AND fi.item_id = v.item_id

mapper.select:
SELECT FROM feed_items fi WHERE fi.eligible
AND (fi.recommend_ok OR fi.item_type <> 'TRIP' OR fi.has_photo OR fi.stop_count >= 2)
AND fi.recommend_ok
AND fi.author_id <> #{q.viewerId} AND NOT EXISTS ( SELECT 1 FROM user_blocks b WHERE (b.blocker_id = #{q.viewerId} AND b.blocked_id = fi.author_id) OR (b.blocker_id = fi.author_id AND b.blocked_id = #{q.viewerId})) AND NOT EXISTS ( SELECT 1 FROM feed_feedback ff WHERE ff.user_id = #{q.viewerId} AND ff.revoked_at IS NULL AND ((ff.kind = 'HIDE_POST' AND ff.item_type = fi.item_type AND ff.item_id = fi.item_id) OR (ff.kind = 'HIDE_AUTHOR' AND ff.target_user_id = fi.author_id AND ff.expires_at > NOW()))) AND NOT (fi.item_type = 'TRIP' AND EXISTS ( SELECT 1 FROM trip_members tm WHERE tm.trip_id = fi.item_id AND tm.user_id = #{q.viewerId} AND tm.status = 'ACCEPTED'))
AND fi.item_type IN #{type}
AND ( (fi.item_type <> 'TRIP'
AND fi.place_group IN #{group}
AND fi.sub_types && #{subType}
)
OR (fi.item_type = 'TRIP' AND fi.stop_kind_counts IS NOT NULL AND (SELECT COALESCE(SUM((fi.stop_kind_counts ->> kind)::int), 0) FROM unnest() AS kind) >= #{q.chipTripMinStops} AND (SELECT COALESCE(SUM((fi.stop_kind_counts ->> kind)::int), 0) FROM unnest() AS kind) >= #{q.chipTripMinRatio} * GREATEST(fi.stop_count, 1))
)
AND fi.point IS NOT NULL AND ST_DWithin(fi.point, goroute_point(#{q.radiusLat}, #{q.radiusLng}), #{q.radiusMeters})
AND FALSE
AND fi.author_id IN #{author}
AND FALSE
AND fi.province_code IN #{province}
AND FALSE
AND (fi.place_id IN #{place} OR (fi.item_type = 'TRIP' AND ( SELECT COUNT(DISTINCT a.place_ref_id) FROM activities a WHERE a.trip_id = fi.item_id AND a.place_ref_id IN #{place} ) >= 2))
AND fi.point IS NOT NULL AND ST_DWithin(fi.point, goroute_point(#{q.nearLat}, #{q.nearLng}), #{q.nearMeters})
AND FALSE
AND (fi.item_type, fi.item_id) IN (#{k.itemType}, #{k.itemId})
AND fi.published_at > #{q.since} AND fi.impression_count < #{q.maxImpressions}
ORDER BY fi.engagement_score DESC, fi.published_at DESC ORDER BY fi.published_at DESC
LIMIT #{q.limit}
